import{vicePresidents}from"./data.js";import{Timeline}from"./components/Timeline.js";import{SearchBar}from"./components/SearchBar.js";document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("vp-explorer-app"),t=vicePresidents.map((e,t)=>({...e,originalIndex:t})),n=`\n        <div class="controls-wrapper">\n            ${SearchBar()}\n        </div>\n        <div id="timeline-root"></div>\n    `;e.innerHTML=n;const i=document.getElementById("timeline-root"),o=document.getElementById("vp-search");function r(e){i.style.opacity="0",setTimeout(()=>{i.innerHTML=Timeline(e),document.querySelectorAll(".timeline-nav-item").forEach(e=>{e.addEventListener("click",()=>{const t=e.getAttribute("data-target"),n=document.getElementById(t);n&&(n.scrollIntoView({behavior:"smooth",block:"center"}),n.classList.add("highlight"),setTimeout(()=>n.classList.remove("highlight"),1500))})}),i.style.opacity="1"},150)}o.addEventListener("input",function(){const e=o.value.toLowerCase();r(t.filter(t=>{const n=t.name.toLowerCase().includes(e),i=t.electionYear.includes(e);return n||i}))}),r(t)});